<template>
  <view class="avatar-container">
    <!-- 头像展示 -->
    <image class="avatar" :src="avatarUrl" mode="aspectFill"></image>
    <!-- 选择图片按钮 -->
    <button @click="chooseAvatar">更换头像</button>
  </view>
</template>

<script setup>
import { ref } from 'vue';
import  uploadImage  from '../../services/api.js'; // 引入现有上传接口

// 头像地址（初始可设默认头像）
const avatarUrl = ref('https://bug7y.oss-cn-beijing.aliyuncs.com/4ca175a6-1eef-4eda-8d09-2f3f882c5e9f.jpg');

// 选择并上传头像
const chooseAvatar = async () => {
  try {
    // 1. 选择图片
    const [res] = await uni.chooseImage({
      count: 1, // 仅选1张
      sizeType: ['compressed'], // 压缩图片
      sourceType: ['album', 'camera'] // 相册/相机
    });

    // 2. 调用现有OSS上传接口
    const uploadRes = await uploadImage(res.tempFilePaths[0]);
    // 3. 上传成功后更新头像（假设接口返回的地址字段是url）
    if (uploadRes.url) {
      avatarUrl.value = uploadRes.url;
      uni.showToast({ title: '头像更换成功' });
    }
  } catch (err) {
    uni.showToast({ title: '上传失败', icon: 'none' });
    console.error('头像上传失败：', err);
  }
};
</script>

<style scoped>
.avatar-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}
.avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin-bottom: 20px;
  border: 1px solid #eee;
}
</style>